// === Tab: mySketch ===
g = 0.01
airR = 0.01

volume = 3;

rocks = [];
droplets = [];

press = false

function setup() {
	createCanvas(windowWidth -800, windowHeight);
	background(255);
	noStroke();


	rocks.push(new rock(700, 500, 100))
	rocks.push(new rock(800, 400, 50))
	rocks.push(new rock(790, 700, 120))
	rocks.push(new rock(820, 600, 70))
}


function splitDrop(drop, i){
	droplets.splice(i, 1);

	if (drop.size > 3){
		newSize = drop.size - 2

		for (var i=0; i < random(1,3); i++){
			droplets.push(new droplet(drop.pos.x, drop.pos.y, newSize, createVector(random(drop.v.x * 0.9, drop.v.x * 1.1) + random(-2, 2), drop.v.y * -random(0.2, 0.4))))
		}
	}


}

function collide(drop, i){


	for (var j=0; j<rocks.length; j++){
		if (collideCircleCircle(drop.pos.x, drop.pos.y, drop.size, rocks[j].pos.x, rocks[j].pos.y, rocks[j].size)){
			splitDrop(drop,i)
		}
	}

}


function draw() {
	background(0);




	//createDroplets
	for (var i=0; i<volume; i++){
		droplets.push(new droplet(530, 110 + random(-3, 3), 8, createVector(random(3,5))))
	}

	for (var i=0; i<droplets.length; i++){


		droplets[i].update()


		if (droplets[i].life <= 0){
			droplets.splice(i,1);
		} else {
			collide(droplets[i], i)
		}
	}


	for (var j=0; j<rocks.length; j++){
		rocks[j].draw()
	}

		//drawPipe
	fill(255,0,0);
	rect(400,100, 120, 20);
	rect(520,95, 20, 30);
}



function mousePressed() {
	press = true;
}
function mouseReleased(){
    press = false;
}

// === Tab: droplet ===
function droplet (x, y, s, vel){
	this.pos = createVector(x,y);
	this.size = s;
	this.v = createVector(vel.x,vel.y);
	this.a = createVector(0,0);
	this.life = 300

	this.update = function(){


		this.a = createVector(this.v.x * -airR, g*this.size);
		this.v.add(this.a);
		this.pos.add(this.v);

		this.draw()
		this.life -= 1
	}

	this.draw = function(){

		fill(0,(10-this.size) * 40, 235);
		ellipse(this.pos.x, this.pos.y, this.size);
	}


}

// === Tab: rock ===
function rock(x, y, s){
	this.pos = createVector(x,y)
	this.size = s

	this.draw = function(){
		fill(200,200,200);
		ellipse(this.pos.x, this.pos.y, this.size);

		if (press == true){
			if (collidePointCircle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))),this.pos.x,this.pos.y,this.size)){
				this.pos.x = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))
				this.pos.y = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))
			}
		}
	}
}

